import { useEffect, useRef } from "react";
import { useLocation } from "react-router";

export function usePageTitle(title) {
  useEffect(() => { document.title = `${title} | Codestead`; }, [title]);
}

export function RouteHeading({ children }) {
  const ref = useRef(null);
  const location = useLocation();
  useEffect(() => {
    if (location.key === "default") return;   // the first page load: leave focus alone.
    ref.current?.focus();
  }, [location.key]);
  return <h1 ref={ref} tabIndex={-1}>{children}</h1>;
}

function CoursePage({ course }) {
  usePageTitle(course.title);
  return <RouteHeading>{course.title}</RouteHeading>;
}
```

| After navigation | Why |
|---|---|
| title names the view. | tabs, history and screen readers use it. |
| focus on main h1. | screen readers read it; Tab continues from there. |
| tabIndex -1 on h1. | focusable by script, skipped by Tab. |
| first load untouched. | the browser already handles it. |

